class BSTIterator:
    def __init__(self, root):
        self.stack = []
        self._push_left(root)

    def _push_left(self, node):
        while node:
            self.stack.append(node)
            node = node.left

    def next(self):
        node = self.stack.pop()
        self._push_left(node.right)
        return node.val

    def hasNext(self):
        return bool(self.stack)

def find_target(root, k):
    def smallest_first(node):
        stack = []
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            yield node.val
            node = node.right

    def largest_first(node):
        stack = []
        while stack or node:
            while node:
                stack.append(node)
                node = node.right
            node = stack.pop()
            yield node.val
            node = node.left

    low_iter = smallest_first(root)
    high_iter = largest_first(root)
    low = next(low_iter)
    high = next(high_iter)
    while low < high:
        total = low + high
        if total == k:
            return True
        if total < k:
            low = next(low_iter)
        else:
            high = next(high_iter)
    return False

def largest_bst(root):
    best = 0

    def visit(node):
        nonlocal best
        if node is None:
            return True, 0, float("inf"), float("-inf")
        left_ok, left_size, left_min, left_max = visit(node.left)
        right_ok, right_size, right_min, right_max = visit(node.right)
        if left_ok and right_ok and left_max < node.val < right_min:
            size = left_size + right_size + 1
            best = max(best, size)
            return True, size, min(left_min, node.val), max(right_max, node.val)
        return False, 0, 0, 0

    visit(root)
    return best
